$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$rows=@(Get-Process -ErrorAction SilentlyContinue|Where-Object {$_.ProcessName -match '^(Docker Desktop|com\.docker\..*|docker.*|vpnkit)$'}|Sort-Object Id|ForEach-Object {[pscustomobject]@{pid=$_.Id;name=$_.ProcessName;created=$_.StartTime.ToUniversalTime().ToFileTimeUtc().ToString([Globalization.CultureInfo]::InvariantCulture)}});[Console]::Out.Write((ConvertTo-Json -InputObject $rows -Compress))